// Normalize RESO fields into the Listing shape in lib/acquisition/types.ts.
// This is the ONLY place that knows the feed's field names; swap the feed by
// rewriting this node alone.
const SUBTYPE = {
  SingleFamilyResidence: 'single-family',
  Duplex: 'duplex',
  Triplex: 'triplex',
  Quadruplex: 'quadplex',
};

return ($input.first().json.value || [])
  .map((p) => {
    const kind = SUBTYPE[p.PropertySubType];
    if (!kind) return null; // 5+ units and everything else drops here
    return {
      json: {
        listingKey: String(p.ListingKey),
        listingId: String(p.ListingId),
        kind,
        listPrice: p.ListPrice,
        livingArea: p.LivingArea || undefined,
        lotSizeSqft: p.LotSizeSquareFeet || undefined,
        yearBuilt: p.YearBuilt || undefined,
        bedrooms: p.BedroomsTotal || undefined,
        bathrooms: p.BathroomsTotalInteger || undefined,
        address: {
          street: [p.StreetNumber, p.StreetName].filter(Boolean).join(' '),
          city: p.City,
          county: p.CountyOrParish,
          state: p.StateOrProvince,
          postalCode: p.PostalCode,
        },
        publicRemarks: p.PublicRemarks || '',
        privateRemarks: p.PrivateRemarks || undefined,
        daysOnMarket: p.DaysOnMarket || undefined,
        photos: (p.Media || [])
          .filter((m) => m.MediaURL)
          .sort((a, b) => (a.Order ?? 0) - (b.Order ?? 0))
          .slice(0, 12)
          .map((m) => m.MediaURL),
        listAgent: {
          fullName: p.ListAgentFullName || 'Listing Agent',
          email: p.ListAgentEmail || undefined,
          phone: p.ListAgentPreferredPhone || undefined,
          mlsId: p.ListAgentMlsId || undefined,
          brokerageName: p.ListOfficeName || undefined,
        },
        standardStatus: p.StandardStatus,
        modificationTimestamp: p.ModificationTimestamp,
      },
    };
  })
  .filter(Boolean);
